#!/usr/bin/env python3
"""Build a source-pinned screen/state review for PDF Studio's new 3D viewer."""
from __future__ import annotations

import hashlib
import html
import json
import subprocess
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
REPO = '/tmp/openaec-inventory/open-pdf-studio'
COMMIT = 'ae1d787e95e70dbf0b24501a7ca0275e61deb92f'
PREFIX = 'open-pdf-studio/'
VIEW = PREFIX + 'js/solid/components/ThreeDView.jsx'
GATE = PREFIX + 'js/solid/components/ThreeDLazy.jsx'
CSS = PREFIX + 'styles/panels.css'


def source(path: str) -> str:
    return subprocess.check_output(['git', '-C', REPO, 'show', f'{COMMIT}:{path}'], text=True)


view, gate, css = source(VIEW), source(GATE), source(CSS)
for fragment in ('threed-toolbar', 'threed-tree', 'threed-canvas', 'threed-snapshot-bar', 'modeSolid', 'modeEdges', 'modeWire', 'modeXray', 'editAsPage'):
    assert fragment in view or fragment in css, fragment
assert "activeDoc()?.threeD?.length" in gate and "activeDoc()?.threeDSnapshots?.length" in gate
begin = css.index('/* ── 3D PDF view')
end = css.index('.threed-toolbar button.threed-markup-btn', begin)
end = css.index('\n', end)
source_css = css[begin:end]
assert 'width: 260px' in source_css and 'width: 220px' in source_css

states = [
    {'id': 'inline', 'label': 'Ingesloten', 'evidence': 'InlineHost plaatst de viewer over de /3D-annotatie en dockt toolbar en boom boven/links van het documentvlak.'},
    {'id': 'expanded', 'label': 'Vergroot', 'evidence': 'expandedHere monteert ThreeDViewer zonder compact; de view vult .main-view.'},
    {'id': 'loading', 'label': 'Laden', 'evidence': 'De canvas toont de vertaalde voortgangstekst totdat ready of error waar is.'},
    {'id': 'error', 'label': 'Fout', 'evidence': 'Een decodeer-, laad- of unsupported-formatfout vervangt de laadtekst.'},
    {'id': 'snapshot', 'label': 'Snapshotpagina', 'evidence': 'ThreeDSnapshotBar toont paginanaam en terugknop alleen op een 3D-markuppagina.'},
]
manifest = {
    'repository': 'open-pdf-studio', 'commit': COMMIT,
    'scope': '3D PDF UI source and CSS states, not a runtime capture or a real U3D model',
    'source_files': [
        {'path': path, 'sha256': hashlib.sha256(text.encode()).hexdigest(), 'url': f'https://github.com/OpenAEC-Foundation/open-pdf-studio/blob/{COMMIT}/{path}'}
        for path, text in ((VIEW, view), (GATE, gate), (CSS, css))
    ],
    'source_css_metrics': {'expanded_tree_width_px': 260, 'compact_tree_width_px': 220,
                           'expanded_toolbar_padding_px': [5, 10], 'compact_toolbar_padding_px': [3, 6],
                           'expanded_toolbar_gap_px': 10, 'compact_toolbar_gap_px': 6,
                           'expanded_toolbar_font_px': 12, 'compact_toolbar_font_px': 11},
    'states': states,
    'prototype_data': 'Fictional model names, geometry, statistics, sheet title and snapshot name; source-linked chrome and controls only.',
    'limitations': ['No captured running PDF Studio image', 'No actual U3D decoding or PDF canvas', 'No claim of pixel equality for surrounding app chrome'],
}
(ROOT / 'harmonization/pdf-main-three-d-screen.json').write_text(json.dumps(manifest, ensure_ascii=False, indent=2) + '\n')

src_link = f'https://github.com/OpenAEC-Foundation/open-pdf-studio/blob/{COMMIT}/'
buttons = ''.join(f'<button type="button" data-state="{x["id"]}">{x["label"]}</button>' for x in states)
notes = ''.join(f'<li><strong>{x["label"]}</strong> — {html.escape(x["evidence"])}</li>' for x in states)
page = '''<!doctype html><html lang="nl"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>PDF-main · 3D-schermreview</title><style>
*{box-sizing:border-box}body{margin:0;background:#f5f4f2;color:#282830;font:14px/1.5 system-ui,sans-serif}header{background:#36363e;color:white;padding:27px max(24px,calc((100vw - 1120px)/2))}header small{color:#f4bd70;letter-spacing:.13em}header h1{font-weight:550;margin:6px 0;font-size:27px}header p{max-width:840px;margin:0;color:#e2e0e5}main{max-width:1168px;margin:auto;padding:24px}.notice{background:#fff4e2;border-left:3px solid #d97706;padding:12px 16px;margin-bottom:16px}.switch{display:flex;gap:7px;flex-wrap:wrap;margin:0 0 15px}.switch button{font:inherit;border:1px solid #bdbbc1;background:white;color:#303038;padding:8px 14px;border-radius:4px;cursor:pointer}.switch button.active{background:#36363e;color:white;border-color:#36363e}.stage{height:650px;background:#b9b8b9;position:relative;overflow:hidden;border:1px solid #aeaaad;box-shadow:0 10px 25px #25232916}.paper{position:absolute;left:17%;top:20px;width:66%;height:750px;background:#fff;box-shadow:0 3px 14px #0003;padding:34px;color:#272730}.paper-head{display:flex;justify-content:space-between;border-bottom:1px solid #bbb;padding-bottom:8px;font-size:12px}.paper h2{font-size:17px;font-weight:500;margin:25px 0 10px}.paper p{color:#777;font-size:12px}.viewer-frame{position:absolute;left:19%;right:19%;top:140px;height:430px;z-index:2;box-shadow:0 0 0 1px #bbb}.stage .threed-view{position:absolute}.stage[data-state="inline"] .viewer-frame,.stage[data-state="snapshot"] .viewer-frame{display:block}.stage[data-state="expanded"] .viewer-frame,.stage[data-state="loading"] .viewer-frame,.stage[data-state="error"] .viewer-frame{inset:0;height:auto;box-shadow:none}.stage[data-state="snapshot"] .viewer-frame{display:none}.stage[data-state="inline"] .threed-view{background:transparent}.stage[data-state="inline"] .threed-toolbar{background:rgba(40,40,46,.85);color:#eee;padding:3px 6px;gap:6px;font-size:11px}.stage[data-state="inline"] .threed-toolbar select,.stage[data-state="inline"] .threed-toolbar button{font-size:11px;padding:1px 6px}.stage[data-state="inline"] .threed-tree{width:220px;background:rgba(40,40,46,.92);color:#eee}.stage[data-state="inline"] .threed-title,.stage[data-state="inline"] .threed-hint{display:none}.stage[data-state="loading"] .model,.stage[data-state="error"] .model{display:none}.stage[data-state="loading"] .threed-loading:not(.threed-error){display:flex}.stage[data-state="error"] .threed-error{display:flex}.stage[data-state="snapshot"] .snapshot{display:flex}.stage[data-state="snapshot"] .viewer-frame{display:none}.stage .threed-loading{display:none}.snapshot{display:none;position:absolute;top:0;left:0;right:0;z-index:3;align-items:center;gap:12px;padding:8px 12px}.snapshot button{margin-left:auto;border:1px solid #bdcbe1;background:#294e7b;color:white;padding:4px 8px}.model{height:100%;display:flex;align-items:center;justify-content:center}.model svg{width:min(80%,520px);height:auto}.model-note{position:absolute;right:14px;bottom:12px;font-size:11px;color:#777;background:#fffd;padding:3px 7px}.threed-canvas{overflow:hidden}.threed-tree-row input{accent-color:#d97706}.evidence{background:white;border:1px solid #ddd9dd;padding:18px;margin-top:18px}.evidence h2{font-size:17px;margin:0 0 6px}.evidence ul{padding-left:20px;margin:6px 0 12px}.evidence li{margin:4px 0}.evidence a{color:#925509}.evidence small{color:#777}.attribution{margin-top:12px;color:#62616b;font-size:12px}@media(max-width:800px){main{padding:14px}.stage{height:530px}.paper{left:6%;width:88%}.viewer-frame{left:7%;right:7%;height:360px}.threed-toolbar{gap:5px}.threed-hint,.threed-stats{display:none}}
''' + source_css + '''</style><header><small>OPENAEC · PUBLIEKE PDF-MAIN</small><h1>3D-weergave: scherm- en toestandreview</h1><p>De actuele bron levert een ingesloten model, een vergrote documentweergave, laad- en fouttoestand en een markuppagina met terugkeer naar het model. De toolbar- en boomstijl hieronder komt uit de gepinde CSS.</p></header><main><div class="notice">Brongetrouwe UI-structuur en maten, met fictieve modelinhoud. Zonder draaiende 3D-PDF en bronscreenshot is dit nog geen pixelvalidatie van de volledige app.</div><div class="switch" role="group" aria-label="3D-schermtoestanden">''' + buttons + '''</div><div class="stage" id="stage" data-state="inline"><div class="paper"><div class="paper-head"><strong>TECHNISCHE TEKENING · VOORBEELD</strong><span>16-10-2026</span></div><h2>3D-model op PDF-pagina</h2><p>Voorbeeldpagina voor visuele beoordeling; geen bronbestand.</p></div><div class="snapshot pdfa-bar threed-snapshot-bar"><svg width="16" height="16" viewBox="0 0 16 16" fill="none" stroke="currentColor" stroke-width="1.3" aria-hidden="true"><path d="M8 1.5l5.5 3v7L8 14.5l-5.5-3v-7z"/><path d="M2.5 4.5L8 7.5l5.5-3M8 7.5v7"/></svg><span>3D markup page: Markup view 1</span><button type="button" id="back">Back to 3D model</button></div><div class="viewer-frame"><div class="threed-view"><div class="threed-toolbar"><span class="threed-title">3D view</span><label>View <select><option>Default view</option><option>Top view</option><option>Markup view 1 (page 2)</option></select></label><button type="button">Fit</button><label>Display <select id="renderMode"><option>Solid</option><option>Solid with edges</option><option>Wireframe</option><option>Transparent</option></select></label><button type="button" class="active" id="treeToggle">Model tree</button><button type="button" class="threed-markup-btn">Edit</button><span class="threed-stats">12 objects, 4,284 triangles</span><span style="flex:1"></span><span class="threed-hint">Left drag: orbit, right drag: pan, wheel: zoom</span><button type="button" id="sizeToggle" title="Fill the document area">⤢</button><button type="button" id="close" class="threed-close" title="Turn off the 3D view">×</button></div><div class="threed-body"><div class="threed-tree" id="tree"><div class="threed-tree-group"><div class="threed-tree-row"><span class="threed-tree-arrow">▼</span><input type="checkbox" checked><span class="threed-tree-name">Example assembly</span><span class="threed-tree-count">3</span></div><div class="threed-tree-row threed-tree-model"><input type="checkbox" checked><span class="threed-tree-name">Housing</span></div><div class="threed-tree-row threed-tree-model"><input type="checkbox" checked><span class="threed-tree-name">Shaft</span></div><div class="threed-tree-row threed-tree-model"><input type="checkbox" checked><span class="threed-tree-name">Base plate</span></div></div></div><div class="threed-canvas"><div class="model"><svg viewBox="0 0 600 400" role="img" aria-label="Fictieve 3D-voorbeeldgeometrie"><defs><linearGradient id="g" x1="0" y1="0" x2="1" y2="1"><stop stop-color="#eff3f8"/><stop offset="1" stop-color="#8995a6"/></linearGradient></defs><path d="M110 260 285 160 490 245 320 350Z" fill="#aab3c0" stroke="#536070" stroke-width="2"/><path d="M160 235 160 150 280 84 410 140 410 245 300 308Z" fill="url(#g)" stroke="#536070" stroke-width="2"/><path d="M160 150 280 215 410 140M280 215v93" fill="none" stroke="#536070" stroke-width="2"/><ellipse cx="285" cy="150" rx="48" ry="20" fill="#eef2f7" stroke="#536070" stroke-width="2"/><path d="M237 150V88c0-26 96-26 96 0v62" fill="url(#g)" stroke="#536070" stroke-width="2"/><ellipse cx="285" cy="88" rx="48" ry="20" fill="#d4dce6" stroke="#536070" stroke-width="2"/><path d="M90 268 315 382 515 269" fill="none" stroke="#7f8b9b" stroke-width="2" opacity=".45"/></svg><span class="model-note">Fictief model · geen U3D-render</span></div><div class="threed-loading">Loading 3D model... 46%</div><div class="threed-loading threed-error">The 3D model could not be read.</div></div></div></div></div></div><div class="evidence"><h2>Toestandbewijs uit de bron</h2><ul>''' + notes + '''</ul><p>CSS-maten: 260 px modelboom in de vergrote weergave, 220 px ingesloten; toolbar 12/11 px tekst met 10/6 px tussenruimte. De vier weergavemodi en de actie <em>Edit</em> staan in de JSX. De snapshotstatus gebruikt de enige nieuwe letterlijke SVG-vorm in dit scherm: een 16 px statusmarkering, geen lintopdracht.</p><p><a href="''' + src_link + VIEW + '''">ThreeDView.jsx</a> · <a href="''' + src_link + GATE + '''">ThreeDLazy.jsx</a> · <a href="''' + src_link + CSS + '''#L1597">panels.css</a> · <a href="../harmonization/pdf-main-three-d-screen.json">Bronmanifest</a></p><small>De checkboxen, selecties en 3D-afbeelding in deze review voeren geen PDF- of WebGL-functie uit.</small></div></main><script>const stage=document.getElementById('stage'),buttons=[...document.querySelectorAll('[data-state]')].filter(x=>x.tagName==='BUTTON');function select(state){stage.dataset.state=state;for(const b of buttons)b.classList.toggle('active',b.dataset.state===state);document.getElementById('sizeToggle').textContent=state==='inline'?'⤢':'⤡';document.getElementById('tree').style.display=state==='snapshot'?'none':''}for(const b of buttons)b.addEventListener('click',()=>select(b.dataset.state));document.getElementById('sizeToggle').addEventListener('click',()=>select(stage.dataset.state==='inline'?'expanded':'inline'));document.getElementById('back').addEventListener('click',()=>select('inline'));document.getElementById('close').addEventListener('click',()=>select('snapshot'));document.getElementById('treeToggle').addEventListener('click',e=>{const tree=document.getElementById('tree');tree.style.display=tree.style.display==='none'?'':'none';e.currentTarget.classList.toggle('active',tree.style.display!=='none')});select('inline')</script></html>'''
(ROOT / 'design/pdf-main-three-d-screen-review.html').write_text(page)
print('PDF 3D screen review: 5 source-backed states, source CSS embedded')
